// ─── File: FeedDemo.java ───
// Hybrid feed: fanout-on-write for normal users, fanout-on-read for celebrities, merged.
// Each class below would be its own file in a real project.
package com.bank.feed;

import java.util.*;
import java.util.logging.*;

public class FeedDemo {

    private static final Logger log = Logger.getLogger("Feed");

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        log.setUseParentHandlers(false);
        log.addHandler(handler);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        FollowGraph graph = new FollowGraph();
        // Rajesh follows two normal analysts and one celebrity index account.
        graph.follow("RAJESH", "ANALYST-A", 500);          // normal: 500 followers
        graph.follow("RAJESH", "ANALYST-B", 2000);         // normal
        graph.follow("RAJESH", "INDEX-NIFTY", 5_000_000);  // celebrity: 5M followers

        FanoutOnWrite push = new FanoutOnWrite(graph);
        FanoutOnRead pull = new FanoutOnRead();
        FeedService feed = new FeedService(graph, push, pull);

        // Normal authors post → fanout-on-WRITE into each follower's precomputed timeline.
        feed.post("ANALYST-A", "Banking sector up 2%");
        feed.post("ANALYST-B", "Rate decision at 2pm");

        // Celebrity posts → NO fanout to 5M timelines; stored for fanout-on-READ merge.
        feed.post("INDEX-NIFTY", "Nifty hits all-time high");

        // Build Rajesh's feed: precomputed (push) + celebrity pulled-and-merged (read).
        List<String> rajeshFeed = feed.buildFeed("RAJESH");
        log.info(() -> "Rajesh feed = " + rajeshFeed);
    }
}

// ─── graph/FollowGraph.java ───  follows + follower counts (celebrity detection)
class FollowGraph {
    private final Map<String, List<String>> followers = new HashMap<>();   // author → followers
    private final Map<String, List<String>> following = new HashMap<>();   // user → followees
    private final Map<String, Long> followerCount = new HashMap<>();

    void follow(String user, String author, long authorFollowerCount) {
        followers.computeIfAbsent(author, k -> new ArrayList<>()).add(user);
        following.computeIfAbsent(user, k -> new ArrayList<>()).add(author);
        followerCount.put(author, authorFollowerCount);
    }
    List<String> followersOf(String author) { return followers.getOrDefault(author, List.of()); }
    List<String> followeesOf(String user) { return following.getOrDefault(user, List.of()); }
    long followerCount(String author) { return followerCount.getOrDefault(author, 0L); }
    boolean isCelebrity(String author) { return followerCount(author) >= 1_000_000; }
}

// ─── write/FanoutOnWrite.java ───  push into each follower's precomputed timeline (O(1) read)
class FanoutOnWrite {
    private static final Logger log = Logger.getLogger("Feed");
    private final FollowGraph graph;
    // per-user precomputed timeline (Redis list in prod), capped
    private final Map<String, Deque<String>> timelines = new HashMap<>();

    FanoutOnWrite(FollowGraph graph) { this.graph = graph; }

    void fanout(String author, String post) {   // async in prod (queue) — write amplification here
        List<String> fol = graph.followersOf(author);
        for (String f : fol) {
            Deque<String> tl = timelines.computeIfAbsent(f, k -> new ArrayDeque<>());
            tl.addFirst(post);
            while (tl.size() > 800) tl.removeLast();   // cap storage
        }
        log.info(() -> "fanout-on-WRITE: pushed '" + post + "' into " + fol.size() + " timelines");
    }
    List<String> timelineOf(String user) { return new ArrayList<>(timelines.getOrDefault(user, new ArrayDeque<>())); }
}

// ─── read/FanoutOnRead.java ───  store celebrity posts once; pull + merge at read time
class FanoutOnRead {
    private static final Logger log = Logger.getLogger("Feed");
    private final Map<String, List<String>> celebPosts = new HashMap<>();  // cached recent posts

    void store(String author, String post) {
        celebPosts.computeIfAbsent(author, k -> new ArrayList<>()).add(0, post);
        log.info(() -> "fanout-on-READ: stored celebrity post '" + post + "' (NOT fanned out)");
    }
    List<String> recent(String author) { return celebPosts.getOrDefault(author, List.of()); }
}

// ─── feed/FeedService.java ───  the HYBRID router + assembler
class FeedService {
    private static final Logger log = Logger.getLogger("Feed");
    private final FollowGraph graph;
    private final FanoutOnWrite push;
    private final FanoutOnRead pull;

    FeedService(FollowGraph graph, FanoutOnWrite push, FanoutOnRead pull) {
        this.graph = graph; this.push = push; this.pull = pull;
    }

    // choose strategy PER AUTHOR by follower count
    void post(String author, String content) {
        if (graph.isCelebrity(author)) pull.store(author, content);   // no 5M-timeline write storm
        else push.fanout(author, content);                           // precompute follower timelines
    }

    // assemble: precomputed timeline + pulled celebrity posts, merged
    List<String> buildFeed(String user) {
        List<String> result = new ArrayList<>(push.timelineOf(user));         // O(1) precomputed part
        for (String author : graph.followeesOf(user))
            if (graph.isCelebrity(author)) result.addAll(pull.recent(author)); // merge few celebs
        // real impl: merge by timestamp/score + dedupe + paginate
        log.fine(() -> "built hybrid feed for " + user);
        return result;
    }
}

class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
